import Foundation
import XCTest
@testable import FrankenTermKit

/// Every positive fixture was independently generated by OpenSSL, and all four
/// encodings were read by ssh-keygen before their shared identity was recorded.
/// On Apple, TestCryptography is the actual CryptoKit-backed AppleCryptography.
@MainActor
final class LegacyECDSASourceKeyTests: XCTestCase {
    private let crypto = TestCryptography()

    private struct Fixtures: Decodable {
        struct Key: Decodable {
            let id, curve, algorithm, fingerprint, publicKey, scalarHex: String
            let sec1PEM, pkcs8PEM, sec1WithoutPublicPEM, pkcs8WithoutPublicPEM: String
            var forms: [String] { [sec1PEM, pkcs8PEM, sec1WithoutPublicPEM, pkcs8WithoutPublicPEM] }
            var profile: SSHECDSACurve { SSHECDSACurve(rawValue: curve)! }
            var publicBlob: Data { Data(base64Encoded: publicKey.split(separator: " ")[1].description)! }
            var point: Data {
                get throws {
                    var reader = ByteCursor(publicBlob)
                    _ = try reader.sshString(); _ = try reader.sshString()
                    return try reader.sshString()
                }
            }
        }
        let keys: [Key]
        static func load() throws -> Self {
            var root = URL(fileURLWithPath: #filePath)
            for _ in 0..<6 { root.deleteLastPathComponent() }
            return try JSONDecoder().decode(Self.self,
                from: Data(contentsOf: root.appendingPathComponent("fixtures/ios-airgap/legacy-ecdsa-source-keys.json")))
        }
    }

    private func workspace(algorithm: String, fingerprint: String) throws -> WorkspaceDocument {
        var root = try JSONSerialization.jsonObject(with: sampleManifest(fingerprint: fingerprint)) as! [String: Any]
        var workspace = root["workspace"] as! [String: Any]
        var credentials = workspace["credentials"] as! [[String: Any]]
        credentials[0]["algorithm"] = algorithm
        workspace["credentials"] = credentials; root["workspace"] = workspace
        return try WorkspaceDocument(data: JSONSerialization.data(withJSONObject: root, options: [.sortedKeys]))
    }

    private func privateScalar(_ record: PrivateKeyRecord, curve: SSHECDSACurve) throws -> Data {
        var outer = ByteCursor(record.container)
        XCTAssertEqual(try outer.take(15), Data("openssh-key-v1\0".utf8))
        XCTAssertEqual(try outer.sshString(), Data("none".utf8))
        XCTAssertEqual(try outer.sshString(), Data("none".utf8))
        XCTAssertTrue(try outer.sshString().isEmpty)
        XCTAssertEqual(try outer.uint(4), 1)
        XCTAssertEqual(try outer.sshString(), record.publicBlob)
        var inner = ByteCursor(try outer.sshString())
        XCTAssertEqual(outer.remaining, 0)
        XCTAssertEqual(try inner.uint(4), try inner.uint(4))
        XCTAssertEqual(try inner.sshString(), Data(curve.algorithm.utf8))
        XCTAssertEqual(try inner.sshString(), Data(curve.rawValue.utf8))
        _ = try inner.sshString()
        return try inner.sshScalar(curve: curve)
    }

    func testAllIndependentSEC1AndPKCS8FormsPreserveExactPrivateAndPublicIdentity() async throws {
        let fixtures = try Fixtures.load()
        XCTAssertEqual(fixtures.keys.count, 6)
        XCTAssertEqual(Set(fixtures.keys.map(\.curve)), Set(SSHECDSACurve.allCases.map(\.rawValue)))
        for fixture in fixtures.keys {
            for pem in fixture.forms {
                let source = try OpenSSHSourceKey(pem: Data(pem.utf8), using: crypto)
                XCTAssertEqual(source.algorithm, fixture.algorithm, fixture.id)
                XCTAssertEqual(source.publicBlob, fixture.publicBlob, fixture.id)
                XCTAssertEqual(source.fingerprint(using: crypto), fixture.fingerprint, fixture.id)
                XCTAssertFalse(source.isEncrypted)
                XCTAssertNil(source.bcryptRounds)
                let record = try source.unlock(credentialID: "key", using: crypto)
                XCTAssertEqual(try privateScalar(record, curve: fixture.profile), try Data(ftHex: fixture.scalarHex), fixture.id)
                XCTAssertEqual(try PrivateKeyRecord.validateContainer(record.container, using: crypto), fixture.publicBlob)
                let direct = try PrivateKeyRecord.fromPEM(Data(pem.utf8), credentialID: "key", using: crypto)
                XCTAssertEqual(try privateScalar(direct, curve: fixture.profile), try Data(ftHex: fixture.scalarHex))
            }
        }
    }

    func testActualPickerAndAuthenticatedArchiveAcceptEveryLegacyForm() async throws {
        for fixture in try Fixtures.load().keys {
            let workspace = try workspace(algorithm: fixture.algorithm, fingerprint: fixture.fingerprint)
            for pem in fixture.forms {
                var picker = OpenSSHSourceKeyUnlocker(using: crypto)
                guard case .ready(let key) = try picker.select(pem: Data(pem.utf8), reference: workspace.credentials[0]) else {
                    return XCTFail("A clear PEM file must not request a passphrase.")
                }
                XCTAssertNil(picker.request)
                let archive = try AirGapArchive(workspace: workspace, keys: [key], using: crypto)
                let sealed = try FTAG.seal(archive, using: crypto)
                let restored = try FTAG.open(sealed.envelope, code: sealed.code, using: crypto)
                XCTAssertEqual(restored.workspace.raw, workspace.raw)
                XCTAssertEqual(restored.keys.count, 1)
                XCTAssertEqual(restored.keys[0].container, key.container)
                XCTAssertEqual(restored.keys[0].publicBlob, fixture.publicBlob)
                XCTAssertEqual(try privateScalar(restored.keys[0], curve: fixture.profile), try Data(ftHex: fixture.scalarHex))
                XCTAssertNil(restored.keys[0].container.range(of: Data("PRIVATE KEY".utf8)))
            }
        }
    }

    func testWrongApprovedIdentityAndUnexpectedPassphraseAreRejected() async throws {
        let fixtures = try Fixtures.load().keys
        for fixture in fixtures {
            let other = try XCTUnwrap(fixtures.first { $0.curve == fixture.curve && $0.id != fixture.id })
            let wrong = try workspace(algorithm: other.algorithm, fingerprint: other.fingerprint)
            var picker = OpenSSHSourceKeyUnlocker(using: crypto)
            XCTAssertThrowsError(try picker.select(pem: Data(fixture.sec1PEM.utf8), reference: wrong.credentials[0])) {
                XCTAssertEqual($0 as? OpenSSHSourceKeyError, .identityMismatch)
            }
            XCTAssertNil(picker.request)
            let source = try OpenSSHSourceKey(pem: Data(fixture.pkcs8PEM.utf8), using: crypto)
            XCTAssertThrowsError(try source.unlock(passphrase: Data("unused".utf8), credentialID: "key", using: crypto)) {
                XCTAssertEqual($0 as? FTError, .malformed("source_key.unexpected_passphrase"))
            }
        }
    }

    func testEmbeddedPublicPointMustMatchTheActualPrivateScalar() async throws {
        let fixtures = try Fixtures.load().keys
        for fixture in fixtures {
            let other = try XCTUnwrap(fixtures.first { $0.curve == fixture.curve && $0.id != fixture.id })
            for pem in [fixture.sec1PEM, fixture.pkcs8PEM] {
                var bytes = try der(pem)
                let range = try XCTUnwrap(bytes.range(of: fixture.point))
                bytes.replaceSubrange(range, with: try other.point)
                let altered = self.pem(bytes, label: pem.contains("BEGIN EC ") ? "EC PRIVATE KEY" : "PRIVATE KEY")
                XCTAssertThrowsError(try OpenSSHSourceKey(pem: altered, using: crypto))
                // CryptoKit derives from the private scalar, so the production
                // normalizer must check the optional public assertion itself.
                let scalarOnly = LegacyDERProbeCryptography(scalar: try Data(ftHex: fixture.scalarHex))
                XCTAssertThrowsError(try OpenSSHSourceKey(pem: altered, using: scalarOnly)) {
                    XCTAssertEqual($0 as? FTError, .malformed("key.identity"))
                }
            }
        }
    }

    func testMissingPublicPointsAreDerivedOnlyAfterExplicitSelection() async throws {
        for fixture in try Fixtures.load().keys {
            XCTAssertEqual(try LegacyECDSASourceKey(pem: Data(fixture.sec1PEM.utf8)).embeddedPublicBlob, fixture.publicBlob)
            XCTAssertEqual(try LegacyECDSASourceKey(pem: Data(fixture.pkcs8PEM.utf8)).embeddedPublicBlob, fixture.publicBlob)
            for pem in [fixture.sec1WithoutPublicPEM, fixture.pkcs8WithoutPublicPEM] {
                XCTAssertNil(try LegacyECDSASourceKey(pem: Data(pem.utf8)).embeddedPublicBlob)
                XCTAssertEqual(try OpenSSHSourceKey(pem: Data(pem.utf8), using: crypto).publicBlob, fixture.publicBlob)
            }
        }
    }

    func testNativeDERImporterBindsTheRequestedCurveAndCompleteInput() async throws {
        for fixture in try Fixtures.load().keys {
            for pem in fixture.forms {
                let bytes = try der(pem)
                XCTAssertEqual(try crypto.importECDSAPrivateScalar(bytes, curve: fixture.profile), try Data(ftHex: fixture.scalarHex))
                for curve in SSHECDSACurve.allCases where curve != fixture.profile {
                    XCTAssertThrowsError(try crypto.importECDSAPrivateScalar(bytes, curve: curve))
                }
                XCTAssertThrowsError(try crypto.importECDSAPrivateScalar(bytes + Data([0]), curve: fixture.profile))
            }
        }
        XCTAssertThrowsError(try crypto.importECDSAPrivateScalar(Data(), curve: .nistp256))
        XCTAssertThrowsError(try crypto.importECDSAPrivateScalar(Data(repeating: 0, count: 1025), curve: .nistp256))
    }

    func testMalformedDERNeverReachesNativeImport() async throws {
        let fixture = try XCTUnwrap(Fixtures.load().keys.first)
        let clear = try der(fixture.sec1PEM), body = try sequenceBody(clear)
        var zeroScalar = clear
        zeroScalar.replaceSubrange(try XCTUnwrap(clear.range(of: Data(ftHex: fixture.scalarHex))),
                                   with: Data(repeating: 0, count: fixture.profile.scalarBytes))
        var unknownCurve = clear
        let oid = try XCTUnwrap(unknownCurve.range(of: Data([0x2a, 0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07])))
        unknownCurve[oid.upperBound - 1] = 8
        var unusedPublicBits = clear
        let point = try XCTUnwrap(clear.range(of: fixture.point))
        unusedPublicBits[point.lowerBound - 1] = 1
        let malformed: [Data] = [
            clear + Data([0]), clear + clear, Data(clear.dropLast()),
            Data([0x30, 0x80]) + body + Data([0, 0]),
            Data([0x30, 0x82, 0, UInt8(body.count)]) + body,
            tlv(0x30, body + Data([0xa0, 0])),
            zeroScalar, unknownCurve, unusedPublicBits
        ]
        for bytes in malformed {
            XCTAssertThrowsError(try OpenSSHSourceKey(pem: pem(bytes, label: "EC PRIVATE KEY"),
                                                    using: LegacyDERProbeCryptography())) {
                XCTAssertFalse($0 is LegacyDERProbeError, "Malformed input reached native cryptography.")
            }
        }
        XCTAssertThrowsError(try OpenSSHSourceKey(pem: pem(Data(repeating: 0, count: 1025), label: "EC PRIVATE KEY"),
                                                using: LegacyDERProbeCryptography())) {
            XCTAssertFalse($0 is LegacyDERProbeError)
        }
    }

    func testPKCS8RejectsVersionAttributesAndConflictingCurveDeclarations() async throws {
        let fixture = try XCTUnwrap(Fixtures.load().keys.first)
        let ecAlgorithm = tlv(0x06, Data([0x2a, 0x86, 0x48, 0xce, 0x3d, 0x02, 0x01]))
        let wrongCurve = tlv(0x06, Data([0x2b, 0x81, 0x04, 0x00, 0x22]))
        let conflict = tlv(0x30, Data([2, 1, 0]) + tlv(0x30, ecAlgorithm + wrongCurve) + tlv(0x04, try der(fixture.sec1PEM)))
        let original = try sequenceBody(der(fixture.pkcs8PEM))
        var wrongVersion = original; wrongVersion[2] = 1
        for bytes in [conflict, tlv(0x30, wrongVersion), tlv(0x30, original + Data([0xa0, 0]))] {
            XCTAssertThrowsError(try OpenSSHSourceKey(pem: pem(bytes, label: "PRIVATE KEY"),
                                                    using: LegacyDERProbeCryptography())) {
                XCTAssertFalse($0 is LegacyDERProbeError)
            }
        }
        XCTAssertThrowsError(try OpenSSHSourceKey(pem: pem(der(fixture.pkcs8PEM), label: "EC PRIVATE KEY"),
                                                using: LegacyDERProbeCryptography()))
    }

    func testEncryptedLegacyPEMIsExplicitlyUnsupportedWithoutWorkOrPrompt() async throws {
        let fixture = try XCTUnwrap(Fixtures.load().keys.first)
        let protectedPKCS8 = pem(try der(fixture.pkcs8PEM), label: "ENCRYPTED PRIVATE KEY")
        let protectedSEC1 = Data(fixture.sec1PEM.replacingOccurrences(of: "-----BEGIN EC PRIVATE KEY-----\n",
            with: "-----BEGIN EC PRIVATE KEY-----\nProc-Type: 4,ENCRYPTED\nDEK-Info: AES-256-CBC,00112233445566778899AABBCCDDEEFF\n").utf8)
        let reference = try workspace(algorithm: fixture.algorithm, fingerprint: fixture.fingerprint).credentials[0]
        for bytes in [protectedPKCS8, protectedSEC1] {
            var picker = OpenSSHSourceKeyUnlocker(using: LegacyDERProbeCryptography())
            XCTAssertThrowsError(try picker.select(pem: bytes, reference: reference)) {
                XCTAssertEqual($0 as? FTError, .unsupported("source_key.encrypted_pem"))
            }
            XCTAssertNil(picker.request)
        }
    }

    func testCancellationPrecedesNativeDERWork() async throws {
        let bytes = Data(try XCTUnwrap(Fixtures.load().keys.first).pkcs8PEM.utf8)
        let worker = Task.detached {
            withUnsafeCurrentTask { $0?.cancel() }
            return try OpenSSHSourceKey(pem: bytes, using: LegacyDERProbeCryptography())
        }
        do { _ = try await worker.value; XCTFail("Cancelled selection succeeded.") }
        catch is CancellationError {}
        catch { XCTFail("Cancellation entered native import or changed its error: \(error)") }
    }

    func testPassiveDiscoveryUsesEmbeddedMetadataAndHonorsSidecars() async throws {
        let fixture = try XCTUnwrap(Fixtures.load().keys.first)
        let home = FileManager.default.temporaryDirectory.appendingPathComponent("ft-legacy-ec-" + UUID().uuidString)
        let directory = home.appendingPathComponent(".ssh")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let entries = ["sec1": fixture.sec1PEM, "pkcs8": fixture.pkcs8PEM,
                       "private-only": fixture.sec1WithoutPublicPEM, "bad-sidecar": fixture.sec1PEM]
        for (name, contents) in entries { try Data(contents.utf8).write(to: directory.appendingPathComponent(name)) }
        try Data("malformed public identity\n".utf8).write(to: directory.appendingPathComponent("bad-sidecar.pub"))
        let configuration = entries.keys.sorted().map { "Host \($0)\nIdentityFile ~/.ssh/\($0)\n" }.joined()
        let source = try SSHWorkspaceSource(configuration: Data(configuration.utf8))
        let inventory = try source.loadPublicIdentityFiles(for: source.aliases, homeDirectory: home)
        XCTAssertEqual(inventory.files["~/.ssh/sec1"], .present(fixture.publicBlob))
        XCTAssertEqual(inventory.files["~/.ssh/pkcs8"], .present(fixture.publicBlob))
        XCTAssertEqual(inventory.files["~/.ssh/private-only"], .unavailable)
        XCTAssertEqual(inventory.files["~/.ssh/bad-sidecar"], .unavailable)
        try Data((fixture.publicKey + "\n").utf8).write(to: directory.appendingPathComponent("private-only.pub"))
        let withSidecar = try source.loadPublicIdentityFiles(for: source.aliases, homeDirectory: home)
        XCTAssertEqual(withSidecar.files["~/.ssh/private-only"], .present(fixture.publicBlob))
        for (name, contents) in entries {
            XCTAssertEqual(try Data(contentsOf: directory.appendingPathComponent(name)), Data(contents.utf8))
        }
    }

    private func der(_ pem: String) throws -> Data {
        try XCTUnwrap(Data(base64Encoded: pem.split(whereSeparator: \.isNewline).dropFirst().dropLast().joined()))
    }
    private func pem(_ der: Data, label: String) -> Data {
        Data(("-----BEGIN \(label)-----\n" + der.base64EncodedString() + "\n-----END \(label)-----\n").utf8)
    }
    private func sequenceBody(_ der: Data) throws -> Data {
        guard der.count >= 2, der[0] == 0x30 else { throw FTError.malformed("test.der") }
        let width = der[1] < 128 ? 0 : Int(der[1] & 0x7f)
        return Data(der.dropFirst(2 + width))
    }
    private func tlv(_ tag: UInt8, _ body: Data) -> Data {
        let length: Data = body.count < 128 ? Data([UInt8(body.count)])
            : body.count < 256 ? Data([0x81, UInt8(body.count)])
            : Data([0x82, UInt8(body.count >> 8), UInt8(body.count & 255)])
        return Data([tag]) + length + body
    }
}

private enum LegacyDERProbeError: Error { case unexpectedNativeWork }
private struct LegacyDERProbeCryptography: AirGapCryptography {
    let scalar: Data?
    let base = TestCryptography()
    init(scalar: Data? = nil) { self.scalar = scalar }
    func importECDSAPrivateScalar(_ der: Data, curve: SSHECDSACurve) throws -> Data {
        guard let scalar else { throw LegacyDERProbeError.unexpectedNativeWork }
        return scalar
    }
    func sha256(_ bytes: Data) -> Data { base.sha256(bytes) }
    func hmacSHA1(key: Data, message: Data) throws -> Data { try base.hmacSHA1(key: key, message: message) }
    func randomBytes(count: Int) throws -> Data { try base.randomBytes(count: count) }
    func seal(_ plaintext: Data, secret: Data, salt: Data, nonce: Data, aad: Data) throws -> Data { try base.seal(plaintext, secret: secret, salt: salt, nonce: nonce, aad: aad) }
    func open(_ ciphertextAndTag: Data, secret: Data, salt: Data, nonce: Data, aad: Data) throws -> Data { try base.open(ciphertextAndTag, secret: secret, salt: salt, nonce: nonce, aad: aad) }
    func ed25519PublicKey(seed: Data) throws -> Data { try base.ed25519PublicKey(seed: seed) }
    func ecdsaPublicKey(scalar: Data, curve: SSHECDSACurve) throws -> Data { try base.ecdsaPublicKey(scalar: scalar, curve: curve) }
    func bcryptPBKDF(passphrase: Data, salt: Data, rounds: UInt32, outputByteCount: Int) throws -> Data { throw LegacyDERProbeError.unexpectedNativeWork }
    func decryptAESCTR(_ ciphertext: Data, key: Data, iv: Data) throws -> Data { throw LegacyDERProbeError.unexpectedNativeWork }
    func decryptAESCBC(_ ciphertext: Data, key: Data, iv: Data) throws -> Data { throw LegacyDERProbeError.unexpectedNativeWork }
}
